"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9219],{78828:e=>{e.exports=JSON.parse('{"functions":[{"name":"ConeCast","desc":"Casts in a cone shape from the origin of the ray towards its direction, returning\\nevery part whose centre falls within `angle` degrees of the axis.\\n\\n`angle` is the half-angle from the axis, in degrees, so 45 describes a 90-degree\\ncone. If no depth is provided, the ray\'s direction magnitude is used.\\n\\nResults are unordered and unfiltered by line of sight \u2014 a part behind a wall is\\nstill reported. Use `overlapParams` to exclude the caster\'s own character, and\\nfollow up with a raycast if occlusion matters.\\n\\n```lua\\nlocal hits = ConeCast(Ray.new(muzzle.Position, muzzle.CFrame.LookVector * 60), 20)\\n\\nfor _, hit in hits do\\n\\tapplyDamage(hit.part, 1 - hit.angle / 20)\\nend\\n```","params":[{"name":"ray","desc":"Origin and direction of the cone\'s axis","lua_type":"Ray"},{"name":"angle","desc":"Half-angle of the cone in degrees","lua_type":"number"},{"name":"depth","desc":"Cone length (defaults to the ray\'s direction magnitude)","lua_type":"number?"},{"name":"overlapParams","desc":"Filter passed to the underlying bounds query","lua_type":"OverlapParams?"}],"returns":[{"desc":"","lua_type":"{ Result }"}],"function_type":"static","source":{"line":63,"path":"src/Shared/Class/ConeCast.luau"}}],"properties":[],"types":[{"name":"Result","desc":"One hit. Sort on `angle` to get the part nearest the cone\'s axis.","fields":[{"name":"part","lua_type":"BasePart","desc":"Part found inside the cone"},{"name":"angle","lua_type":"number","desc":"Degrees between the ray and the part, within the cone"}],"source":{"line":30,"path":"src/Shared/Class/ConeCast.luau"}}],"name":"ConeCast","desc":"Finds parts inside a cone projected from a ray, for things like flashlight\\ndetection, AI vision, or a shotgun spread.\\n\\nRoblox has no cone query, so this over-selects with\\n`Workspace:GetPartBoundsInBox()` and then filters by the angle between the ray and\\neach part\'s centre.\\n\\nTwo consequences follow from that. The bounding box is a cube of side `depth`, so\\nparts slightly beyond the cone\'s tip can be considered before being angle-filtered.\\nAnd the angle test uses each part\'s *centre* \u2014 a large part whose centre falls\\noutside the cone is missed even when part of it is inside.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":19,"path":"src/Shared/Class/ConeCast.luau"}}')}}]);